// -std=c++20
#include <algorithm>
#include <concepts>
#include <cstdint>
#include <iomanip>
#include <iostream>

template <std::integral T>
T mid(T bid, T ask) {
    return bid + (ask - bid) / 2;  // whole ticks
}

template <std::floating_point T>
T mid(T bid, T ask) {
    return (bid + ask) / 2;
}

template <typename P>
concept Payoff = requires(const P& p, double S, double K) {
    { p(S, K) } -> std::convertible_to<double>;
};

struct Call {
    double operator()(double S, double K) const { return std::max(S - K, 0.0); }
};
struct Put {
    double operator()(double S, double K) const { return std::max(K - S, 0.0); }
};
struct Quote {
    double bid, ask;
};

static_assert(Payoff<Call> && Payoff<Put>);
static_assert(!Payoff<Quote>);

constinit int g_priced = 0;  // zero before main starts, and still changeable

template <Payoff P>
double price(const P& p, double S, double K) {
    ++g_priced;
    return 0.5 * (p(S * 1.1, K) + p(S * 0.9, K));
}

consteval std::int64_t ten_to(int n) {
    std::int64_t p = 1;
    for (int i = 0; i < n; ++i) {
        p *= 10;
    }
    return p;
}

int main() {
    std::cout << mid(std::int64_t{10125}, std::int64_t{10126}) << ' ' << mid(99, 102) << ' '
              << mid(101.25, 101.26) << '\n';
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "call " << price(Call{}, 100.0, 95.0) << ", put " << price(Put{}, 100.0, 95.0) << '\n';
    constexpr std::int64_t scale = ten_to(8);
    std::cout << "priced " << g_priced << ", scale " << scale << '\n';
    return 0;
}

