// -std=c++20
#include <algorithm>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <new>
#include <ranges>
#include <span>
#include <string>
#include <vector>

long g_allocs = 0;
void* operator new(std::size_t n) {
    ++g_allocs;
    void* p = std::malloc(n);
    if (p == nullptr) throw std::bad_alloc{};
    return p;
}
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

struct Fill {
    std::string symbol;
    std::int64_t qty;  // negative for a sell
    std::int64_t px;   // ticks
};

std::int64_t notional(std::span<const Fill> fills) {
    std::int64_t total = 0;
    for (const Fill& f : fills) total += f.qty * f.px;
    return total;
}

int main() {
    std::vector<Fill> fills = {{"AAPL", 100, 19275}, {"MSFT", -50, 41010}, {"AAPL", 200, 19280},
                               {"NVDA", 30, 13950}, {"AAPL", -40, 19290}};
    std::ranges::sort(fills, {}, &Fill::px);  // by price, through a projection
    for (const Fill& f : fills) std::cout << f.symbol << ' ' << f.qty << " @ " << f.px << '\n';

    const long before = g_allocs;
    auto aapl_buys = fills
        | std::views::filter([](const Fill& f) { return f.symbol == "AAPL" && f.qty > 0; })
        | std::views::transform(&Fill::qty);
    std::int64_t bought = 0;
    for (std::int64_t q : aapl_buys) bought += q;
    std::cout << "AAPL bought " << bought << ", allocations " << g_allocs - before << '\n';

    const auto sells = std::ranges::count_if(fills, [](const Fill& f) { return f.qty < 0; });
    const auto nvda = std::ranges::find(fills, "NVDA", &Fill::symbol);
    std::cout << "sells " << sells << ", NVDA qty " << nvda->qty << '\n';

    const std::span<const Fill> all(fills);
    std::cout << "notional " << notional(all) << ", two cheapest " << notional(all.first(2))
              << ", priciest " << notional(all.last(1)) << '\n';
    std::cout << "sizeof(span) " << sizeof(all) << '\n';
    return 0;
}

