#include <algorithm>
#include <compare>
#include <cstdint>
#include <functional>
#include <iostream>
#include <set>
#include <type_traits>
#include <vector>

struct Level {
    std::int64_t px;  // ticks
    std::int64_t qty;
    auto operator<=>(const Level&) const = default;  // all six comparisons, px then qty
};

struct Quote {
    std::int64_t ts_ns;
    double bid;
    double ask;
    auto operator<=>(const Quote&) const = default;
};

int main() {
    const Level a{.px = 19275, .qty = 100};
    const Level b{.px = 19275, .qty = 300};
    const Level c{.px = 19280};  // qty left out, so it's 0
    std::cout << std::boolalpha;
    std::cout << (a < b) << ' ' << (a == b) << ' ' << (a != b) << ' ' << (c > b) << '\n';

    std::vector<Level> bids = {a, c, b};
    std::ranges::sort(bids, std::greater{});  // the best bid first
    for (const Level& l : bids) {
        std::cout << l.px << " x " << l.qty << '\n';
    }
    const std::set<Level> distinct = {a, b, a};
    std::cout << "distinct " << distinct.size() << '\n';

    const Quote q1{.ts_ns = 34200000000000, .bid = 101.25, .ask = 101.27};
    const Quote q2{.ts_ns = 34200000000000, .bid = 101.25, .ask = 101.30};
    std::cout << (q1 < q2) << ' ' << std::is_same_v<decltype(a <=> b), std::strong_ordering> << ' '
              << std::is_same_v<decltype(q1 <=> q2), std::partial_ordering> << '\n';
    return 0;
}

