// -std=c++20
#include <algorithm>
#include <compare>
#include <cstdint>
#include <iostream>
#include <vector>

struct Ask {
    std::int64_t px;     // ticks, the lowest first
    std::int64_t ts_ns;  // arrival time, the earliest first
    std::int64_t qty;
    auto operator<=>(const Ask&) const = default;
};

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<Ask> asks;
    for (int i = 0; i < n; ++i) {
        std::int64_t px = 0;
        std::int64_t ts = 0;
        std::int64_t qty = 0;
        std::cin >> px >> ts >> qty;
        asks.push_back(Ask{.px = px, .ts_ns = ts, .qty = qty});
    }
    std::ranges::sort(asks);
    for (const Ask& a : asks) {
        std::cout << a.px << ' ' << a.ts_ns << ' ' << a.qty << '\n';
    }
    const Ask& best = asks.front();
